 let skel='',skelOffsets=[];for(let i=0;i<folded.length;i++){const ch=folded[i];if(/[a-z0-9]/.test(ch)){skel+=ch;skelOffsets.push(offsets[i])}else if(skel){if(skel.endsWith('\u0001'))skelOffsets[skelOffsets.length-1][1]=offsets[i][1];else{skel+='\u0001';skelOffsets.push([offsets[i][0],offsets[i][1]])}}}
 for(const {re,loose} of maskPatterns){re.lastIndex=0;let m;while((m=re.exec(skel))){const a=skelOffsets[m.index][0],b=skelOffsets[m.index+m[0].length-1][1];if(loose||boundaryOk(a,b))mask.fill(1,a,b)}}
