 const accountKey=p=>typeof p?.key==='string'&&p.key?p.key:String(p?.id||'');
 function sweep(now){if(now<nextSweepAt)return;nextSweepAt=now+1000;for(const [k,v] of pending)if(v.expiresAt<=now)pending.delete(k);for(const [k,u] of cooldowns)if(u<=now)cooldowns.delete(k)}
 function validate(p,allowed){if(!allowed||p?.dead||!p?.eq||p?.tool!=='bloxycola')return{accepted:false,reason:'not-equipped'};if(!Number.isFinite(p.health)||p.health<=0)return{accepted:false,reason:'invalid-health'};const rawMax=Number.isFinite(p.maxHealth)&&p.maxHealth>0?Math.min(10000,p.maxHealth):100;return{accepted:true,maxHealth:Math.max(rawMax,p.health)}}
