 if(!sip)return false;
 const token=sip&&typeof sip==='object'?sip.token:null,reqId=sip&&typeof sip==='object'?sip.reqId:undefined;
 if(expectedToken!==null&&token!==expectedToken)return false;
 if(expectedReqId!==null&&reqId!==expectedReqId)return false;
