 Object.assign(p,{x,y,z,yaw,pitch,bodyRotation,freeSit:!!claim,seatOffset,seatKey,seatAnchor:claim?claim.anchor:null,ph:claim?'sit':phase,mv:claim?0:(m.mv?1:0),eq:claim?0:(tool&&m.eq?1:0),gr:m.gr==='Out'?'Out':'Up',tool,fly:fly?1:0});
