function replaceSession(conn,key,room){
 const previousId=liveAccounts.get(key);if(!previousId||previousId===conn.id)return;
 const previous=players.get(previousId),oldConn=conns.get(previousId);
 // Clean up before closing: a delayed onClose must not clear the new session's ownership.
 if(previous){colaAuthority.cancel(previous);previous.removed=true;release(oldConn||{id:previousId},previous)}else{liveAccounts.delete(key);for(const [ip,id] of liveIps)if(id===previousId)liveIps.delete(ip)}
 players.delete(previousId);conns.delete(previousId);dirty.delete(previousId);
 room.broadcast({type:'left',id:previousId});
 const reason='You joined from another session. This session has been replaced.';
 if(oldConn){try{oldConn.send({type:'sessionReplaced',reason})}catch{}try{oldConn.close(4009,reason)}catch{}}
}


// Room-lifetime grid builds: identity, range, collisions, count and edit permissions are server-owned.
const worldBuilds=new Map(),buildSolids=new Map(),buildExtraSolids=new Map(),buildCounts=new Map(),fineBuildGrid=new Map();
let buildCeiling=40,buildRevision=0;
function legalWalkHeight(){return buildCeiling}
const buildPrefix=config.buildNamespace?config.buildNamespace+':':'';
const buildKey=(x,y,z)=>buildPrefix+x+','+y+','+z;
const wireKey=k=>buildPrefix&&k.startsWith(buildPrefix)?k.slice(buildPrefix.length):k;
const wireBlock=b=>{const {instance,signInstance,...rest}=b;return {...rest,key:wireKey(b.key)}};
function fineGridKey(x,z){return Math.floor(x/8)+','+Math.floor(z/8)}
function* allBuildSolids(){yield* buildSolids.values();for(const parts of buildExtraSolids.values())yield* parts}
function* allWorldSolids(){yield* solidBoxes;yield* allBuildSolids()}
function indexBuild(block){const parts=buildSolidParts(block);for(const solid of parts)solid.buildKey=block.key;buildSolids.set(block.key,parts[0]);if(parts.length>1)buildExtraSolids.set(block.key,parts.slice(1));if([block.x,block.y,block.z].every(Number.isInteger))return;for(const solid of parts){const minX=Math.floor((solid.x-solid.s[0]/2-.8)/8),maxX=Math.floor((solid.x+solid.s[0]/2+.8)/8),minZ=Math.floor((solid.z-solid.s[2]/2-.8)/8),maxZ=Math.floor((solid.z+solid.s[2]/2+.8)/8);solid.gridCells=[];for(let x=minX;x<=maxX;x++)for(let z=minZ;z<=maxZ;z++){const k=x+','+z;let bucket=fineBuildGrid.get(k);if(!bucket)fineBuildGrid.set(k,bucket=new Set());bucket.add(solid);solid.gridCells.push(k)}}}
function unindexBuild(key){for(const solid of [buildSolids.get(key),...(buildExtraSolids.get(key)||[])])if(solid?.gridCells)for(const k of solid.gridCells){const bucket=fineBuildGrid.get(k);bucket?.delete(solid);if(bucket?.size===0)fineBuildGrid.delete(k)}buildSolids.delete(key);buildExtraSolids.delete(key);chairFrameCache.delete(buildPrefix?key.slice(buildPrefix.length):key)}
// #3522 structural support: after a build edit, any player-built block whose
// 6-face support chain no longer reaches the ground plane or authored static
// geometry falls. The support graph uses grid adjacency on the block's own
// coordinate lattice (the same rule placement enforces) plus fine face
// contact via faceNeighbor, so anything placeable never falls and only
// structures that lost their connection drop. Anchors: any part bottom at
// y<=0.02 or face contact with a static map solid. Falls persist to D1
// first, then mutate room state, then broadcast per-key delete updates
// followed by one buildFall animation event. Load-time rows are never
// re-evaluated: existing saved builds only fall when an edit touches their
// region (non-destructive default).
const SUPPORT_BUDGET=12000;
function reportSupport(dbg){try{console.warn('SUPPORT_DEBUG '+JSON.stringify(dbg))}catch{}
  for(const c of conns.values()){if(isAuthenticatedTrey(c.userId,c.username,c.identity))try{c.send({type:'supportDebug',...dbg})}catch{}}}
function supportBlockParts(b){const p0=buildSolids.get(b.key),rest=buildExtraSolids.get(b.key)||[];return p0?[p0,...rest]:buildSolidParts(b)}
function supportStaticTouch(p){if(config.boxes)return false;const boxes=mapGrid.get(Math.floor(p.x/8)+','+Math.floor(p.z/8));if(!boxes)return false;for(const s of boxes)if(!s.buildKey&&!s.removed&&s.collide!==false&&faceNeighbor(p,s))return true;return false}
