  await env.DB.prepare("INSERT INTO friendships (user_low, user_high, low_name, high_name, status, requested_by, created) VALUES (?, ?, ?, ?, 'pending', ?, ?)").bind(lo, hi, names[lo] ?? '', names[hi] ?? '', a, Date.now()).run();
