  try { const builds = await env.DB.prepare("SELECT owner AS id, MAX(username) AS username, COUNT(*) AS builds, SUM(CASE WHEN block_key LIKE 'fbp:%' THEN 1 ELSE 0 END) AS fbp, SUM(CASE WHEN block_key LIKE 'fbh:%' THEN 1 ELSE 0 END) AS fbh, SUM(CASE WHEN block_key NOT LIKE 'fbp:%' AND block_key NOT LIKE 'fbh:%' THEN 1 ELSE 0 END) AS legacy FROM world_builds WHERE owner <> '' AND (? = '' OR username LIKE ? ESCAPE '\\' OR owner = ?) GROUP BY owner ORDER BY builds DESC LIMIT 100").bind(query, like, query).all(); for (const b of builds.results || []) add(b.id, b.username, { builds: Number(b.builds || 0), fbp: Number(b.fbp || 0), fbh: Number(b.fbh || 0), legacy: Number(b.legacy || 0) }); } catch (_) {}
