// Public Roblox username lookup and avatar details. This does not authenticate
// account ownership, and only the R6 body colors are rendered by this demo.

// Public-only delivery fallback. No cookies or arbitrary download hosts.
const assetCache=new Map();let assetCacheBytes=0;
async function upstream(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),3500);try{return await fetch(url,{...options,signal:controller.signal})}finally{clearTimeout(timer)}}
async function publicBytes(response){if(!response.ok)throw Object.assign(Error('Asset provider HTTP '+response.status),{status:response.status});const n=Number(response.headers.get('content-length')||0);if(n>8388608)throw Object.assign(Error('Asset exceeds 8 MB limit'),{status:413});const bytes=await response.arrayBuffer();if(bytes.byteLength>8388608)throw Object.assign(Error('Asset exceeds 8 MB limit'),{status:413});if(!bytes.byteLength)throw Error('Empty asset');if((response.headers.get('content-type')||'').includes('json')){const body=JSON.parse(new TextDecoder().decode(bytes));throw Object.assign(Error(body.errors?.[0]?.message||'Asset delivery error'),{status:body.errors?.[0]?.code||502})}return bytes}
async function downloadPublicAsset(id){let firstError;try{return await publicBytes(await upstream('https://assetdelivery.roblox.com/v1/asset/?id='+id))}catch(e){firstError=e;if(e.status===413)throw e}
try{const r=await upstream('https://assetdelivery.roblox.com/v2/assetId/'+id);if(!r.ok)throw Object.assign(Error('Asset resolver HTTP '+r.status),{status:r.status});const j=await r.json();if(j.errors?.length)throw Object.assign(Error(j.errors[0].message),{status:j.errors[0].code});const location=j.locations?.find(x=>x.location)?.location||j.location;if(!location)throw Error('No public asset location');const url=new URL(location);if(url.protocol!=='https:'||!url.hostname.endsWith('.rbxcdn.com'))throw Error('Unexpected asset host');return await publicBytes(await upstream(url.href,{redirect:'error'}))}catch(e){if([401,403].includes(firstError.status)||[401,403].includes(e.status))throw Object.assign(Error('Roblox requires authentication for this asset; public import is unavailable.'),{status:403});throw e}
}

// Public thumbnail pictures only; never treat these pictures as wearable clothing templates.
async function avatarThumbnails(request,u){
 if(request.method!=='GET')return new Response('Method not allowed',{status:405});
 const raw=u.searchParams.get('ids')||'';
 const parts=raw.split(',');
 if(!raw||parts.length>20||parts.some(id=>!/^\d{1,16}$/.test(id)))return Response.json({ok:false,error:'Expected 1–20 numeric asset IDs.'},{status:400});
 const ids=[...new Set(parts)];
 try{
  const r=await upstream('https://thumbnails.roblox.com/v1/assets?assetIds='+ids.join(',')+'&size=150x150&format=Png&isCircular=false');
  if(!r.ok)throw Error('thumbnail service unavailable');
  const body=await r.json(),out=[];
  for(const d of Array.isArray(body?.data)?body.data:[]){
   const id=String(d?.targetId||'');if(!ids.includes(id)||d?.state!=='Completed'||typeof d.imageUrl!=='string')continue;
   try{const t=new URL(d.imageUrl);if(t.protocol!=='https:'||t.username||t.password||!(t.hostname==='rbxcdn.com'||t.hostname.endsWith('.rbxcdn.com')))continue;out.push({id,url:t.href})}catch{}
  }
  return Response.json({ok:true,items:out},{headers:{'Cache-Control':'public, max-age=300'}});
 }catch{return Response.json({ok:false,items:[],error:'Public thumbnail service unavailable.'},{status:502,headers:{'Cache-Control':'no-store'}})}
}

async function avatarAsset(request,u){if(request.method!=='GET')return new Response('Method not allowed',{status:405});const id=u.searchParams.get('id')||'';if(!/^\d{1,16}$/.test(id))return new Response('Invalid asset id',{status:400});try{let cached=assetCache.get(id);if(cached&&cached.until<Date.now()){assetCacheBytes-=cached.bytes.byteLength;assetCache.delete(id);cached=null}if(!cached){const bytes=await downloadPublicAsset(id);while(assetCache.size&&(assetCacheBytes+bytes.byteLength>33554432||assetCache.size>=64)){const key=assetCache.keys().next().value;assetCacheBytes-=assetCache.get(key).bytes.byteLength;assetCache.delete(key)}cached={bytes,until:Date.now()+300000};assetCache.set(id,cached);assetCacheBytes+=bytes.byteLength}return new Response(cached.bytes,{headers:{'Content-Type':'application/octet-stream','Cache-Control':'public, max-age=1800','X-Content-Type-Options':'nosniff'}})}catch(e){const status=e.status===403?403:e.status===413?413:502;console.warn('Public avatar asset',id,e.message);return new Response(e.message||'Asset service unavailable',{status,headers:{'Cache-Control':'no-store'}})}}


// Fetched characters live in Websim blobs, indexed by D1, so any user reuses them without another provider download.
async function storedCharacter(env,key){if(!env?.DB)return null;try{const row=await env.DB.prepare('SELECT zip_url FROM avatar_characters WHERE username_key = ?').bind(key).first();if(!row?.zip_url)return null;const r=await fetch(row.zip_url);if(!r.ok)return null;const bytes=new Uint8Array(await r.arrayBuffer());return bytes.length>4&&bytes[0]===80&&bytes[1]===75?bytes:null}catch(e){console.warn('Stored character',key,e.message);return null}}
async function keepCharacter(env,key,bytes){if(!env?.DB||!env?.BLOB)return;try{const {url}=await env.BLOB.put('character-'+key+'.zip',bytes,{contentType:'application/zip'});await env.DB.prepare('INSERT INTO avatar_characters (username_key, zip_url, fetched_at) VALUES (?, ?, ?) ON CONFLICT(username_key) DO UPDATE SET zip_url=excluded.zip_url, fetched_at=excluded.fetched_at').bind(key,url,Date.now()).run()}catch(e){console.warn('Keep character',key,e.message)}}
const characterCache=new Map();
async function avatarCharacter(request,u,env){
 if(request.method!=='GET')return new Response('Method not allowed',{status:405});
 const username=(u.searchParams.get('username')||'').trim();if(!/^[A-Za-z0-9_]{1,20}$/.test(username))return Response.json({error:'Enter a valid Roblox username.'},{status:400});
 const key=username.toLowerCase();let cached=characterCache.get(key);
 try{
  if(!cached||cached.until<Date.now()){
   let bytes=await storedCharacter(env,key),lastError;const stored=!!bytes;
   for(let attempt=0;!bytes&&attempt<2;attempt++){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),18000);
    try{const r=await fetch('https://tools.nicolinoo.eu/_actions/tools.characterDownloader.downloadCharacter/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username}),signal:controller.signal});if(!r.ok)throw Error('Character provider HTTP '+r.status);const text=await r.text();if(text.length>44*1024*1024)throw Error('Character zip exceeds limit');const a=JSON.parse(text),entry=a[a[0]?.zipData];if(entry?.[0]!=='ArrayBuffer'||typeof entry[1]!=='string')throw Error('Character provider returned no zip');const raw=atob(entry[1]);bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));if(bytes.length>32*1024*1024||bytes[0]!==80||bytes[1]!==75)throw Error('Character provider returned an invalid zip');break}catch(e){lastError=e}finally{clearTimeout(timer)}
   }
   if(!bytes)throw lastError;if(!stored)await keepCharacter(env,key,bytes);
   // A small in-memory cache; no avatar files are written to the database.
   while(characterCache.size>=4)characterCache.delete(characterCache.keys().next().value);
   cached={bytes,until:Date.now()+300000};characterCache.set(key,cached);
  }
  return new Response(cached.bytes,{headers:{'Content-Type':'application/zip','Cache-Control':'public, max-age=300','X-Content-Type-Options':'nosniff'}});
 }catch(e){console.warn('Character download',username,e.message);return Response.json({error:'Character download failed. Download the zip from the avatar site and upload it here.'},{status:502,headers:{'Cache-Control':'no-store'}})}
}


