 const userId=authed?String(rawUserId).slice(0,128):null;
 if(!authed)return request.method==='GET'?Response.json({config:null,authenticated:false,updatedAt:0},{headers}):Response.json({error:'Sign in to Websim to save your outfit across devices.'},{status:401,headers});
 if(!await ensureAvatarConfig(env))return Response.json({error:'Database is unavailable.'},{status:503,headers});
 const current=async()=>{const row=await env.DB.prepare('SELECT name, config, updated_at FROM avatar_config WHERE user_id = ?').bind(userId).first();if(!row)return null;let config=null;try{config=JSON.parse(row.config)}catch{}return{name:row.name,config,updatedAt:Number(row.updated_at)||0}};
 if(request.method==='GET'){const cur=await current();return Response.json({authenticated:true,userId,name:cur?.name||'',config:cur?.config||null,updatedAt:cur?.updatedAt||0},{headers})}
 if(request.method==='DELETE'){await env.DB.prepare('DELETE FROM avatar_config WHERE user_id = ?').bind(userId).run();return Response.json({ok:true},{headers})}
 if(request.method!=='POST'&&request.method!=='PUT')return new Response('Method not allowed',{status:405});
 if(Number(request.headers.get('content-length')||0)>1048576)return Response.json({error:'Outfit config exceeds 1 MB limit.'},{status:413,headers});
 const text=await request.text();if(text.length>1048576)return Response.json({error:'Outfit config exceeds 1 MB limit.'},{status:413,headers});
 let body;try{body=JSON.parse(text)}catch{return Response.json({error:'Invalid JSON payload.'},{status:400,headers})}
 const name=String(body?.name||'').trim();
 if(!name||name.length>80||/[\x00-\x1f]/.test(name))return Response.json({error:'Invalid outfit name.'},{status:400,headers});
 if(!body?.config||typeof body.config!=='object'||Array.isArray(body.config))return Response.json({error:'config must be a JSON object.'},{status:400,headers});
 const configText=JSON.stringify(body.config);
 if(configText.length>1048576)return Response.json({error:'Outfit config exceeds 1 MB limit.'},{status:413,headers});
 if(configText.includes('data:image/'))return Response.json({error:'Local-only images are never uploaded to the server.'},{status:400,headers});
 let rawIfMatch=request.headers.get('x-if-match-updated-at');
 if(rawIfMatch===null&&u.searchParams.has('ifMatchUpdatedAt'))rawIfMatch=u.searchParams.get('ifMatchUpdatedAt');
