async function robloxFetchRetry(url,init={},tries=2){let lastErr=null;for(let i=0;i<tries;i++){try{const r=await fetch(url,{...init,signal:AbortSignal.timeout(6500)});if(r.ok||r.status===404||r.status===400)return r;lastErr=Error('HTTP '+r.status)}catch(e){lastErr=e}if(i+1<tries)await new Promise(res=>setTimeout(res,350))}throw lastErr||Error('Upstream unavailable')}
export default {async fetch(request,env){const u=new URL(request.url);if(u.pathname==='/api/client-version')return Response.json({version:CLIENT_VERSION,updateRequired:u.searchParams.get('version')!==CLIENT_VERSION},{headers:{'Cache-Control':'no-store'}});if(u.pathname==='/api/tv'||u.pathname==='/api/tv-image')return sharedTV(request,env,u.pathname==='/api/tv-image');if(u.pathname==='/api/user-assets-v2')return userAssetsV2(request,u,env);if(u.pathname==='/api/user-avatars')return userAvatars(request,env);if(u.pathname==='/api/avatar-last')return lastAvatar(request,u,env);if(u.pathname==='/api/studio-place')return studioPlaceApi(request,env);if(u.pathname==='/api/avatar-character')return avatarCharacter(request,u,env);if(u.pathname==='/api/avatar-asset')return avatarAsset(request,u);if(u.pathname==='/api/avatar-thumbnails')return avatarThumbnails(request,u);if(u.pathname==='/api/social')return socialApi(request,env);if(u.pathname==='/api/device')return deviceApi(request,env);if(u.pathname==='/api/admin')return adminApi(request,env);if(u.pathname==='/api/admin-tools')return adminToolsApi(request);if(u.pathname==='/api/catalog-shared')return sharedCatalogApi(request,env);if(u.pathname==='/api/user-collection')return userCollectionApi(request,env);if(u.pathname==='/api/avatar-config')return avatarConfigApi(request,u,env);if(u.pathname!=='/api/avatar')return new Response('Not found',{status:404});if(request.method!=='GET')return new Response('Method not allowed',{status:405});const username=(u.searchParams.get('username')||'').trim();if(!/^[A-Za-z0-9_]{1,20}$/.test(username))return Response.json({error:'Enter a valid Roblox username.'},{status:400,headers:{'Cache-Control':'no-store'}});try{const lookup=await robloxFetchRetry('https://users.roblox.com/v1/usernames/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({usernames:[username],excludeBannedUsers:true})});if(!lookup.ok)throw Error('Roblox user lookup unavailable');const user=(await lookup.json()).data?.[0];if(!user)return Response.json({error:'User not found.'},{status:404,headers:{'Cache-Control':'no-store'}});const id=Number(user.id);if(!Number.isSafeInteger(id)||id<1)throw Error('Invalid Roblox user ID');const [avatar,thumb]=await Promise.all([robloxFetchRetry('https://avatar.roblox.com/v1/users/'+id+'/avatar'),fetch('https://thumbnails.roblox.com/v1/users/avatar?userIds='+id+'&size=420x420&format=Png&isCircular=false',{signal:AbortSignal.timeout(4500)}).catch(()=>null)]);if(!avatar.ok)throw Error('Roblox avatar service unavailable');const a=await avatar.json(),th=thumb?.ok?await thumb.json().catch(()=>null):null;return Response.json({id,name:user.name,displayName:user.displayName,avatarType:a.playerAvatarType,bodyColors:a.bodyColors,palette:STATIC_AVATAR_PALETTE,assets:(a.assets||[]).slice(0,100).map(x=>({id:x.id,name:x.name,assetType:x.assetType?.name})),thumbnail:th?.data?.[0]?.imageUrl||null},{headers:{'Cache-Control':'no-store'}})}catch(e){return Response.json({error:'Roblox avatar lookup is unavailable from this backend.'},{status:502,headers:{'Cache-Control':'no-store'}})}}};